-- order-model-protocol-transformation-bindings.sql
--
-- The declared model protocol transformations carry their `let` bindings in
-- alphabetical member order. The Node lowering evaluates bindings in
-- declaration order and each binding sees only the names already bound, so
-- `resolve-model-alias-embodiment.v1` and
-- `construct-projected-model-invocation.v1` referenced later bindings and
-- rejected every authorized alias. This migration re-declares the two
-- transformations with dependency order preserved (conveyor/request bindings
-- first, then the find bindings that consume them). No value, branch or
-- contract changes; only member order.
--
-- Idempotent: the document digest gate returns UNCHANGED on replay.
--
-- Default: ROLLBACK. Install only after the from-transaction preflight passes:
--   node scripts/run-migration.mjs sql/migrations/order-model-protocol-transformation-bindings.sql
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @trg nvarchar(400), @trgCur CURSOR;
SET @trgCur = CURSOR FOR SELECT QUOTENAME(s.name)+'.'+QUOTENAME(t.name) FROM sys.triggers t JOIN sys.objects o ON o.object_id=t.parent_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.type='U' AND s.name IN ('model','source') AND (t.name LIKE 'guard%' OR t.name LIKE '%immutable%');
OPEN @trgCur; FETCH NEXT FROM @trgCur INTO @trg; WHILE @@FETCH_STATUS=0 BEGIN EXEC(N'DROP TRIGGER '+@trg); FETCH NEXT FROM @trgCur INTO @trg; END
CLOSE @trgCur; DEALLOCATE @trgCur;
BEGIN TRANSACTION;
GO
DECLARE @object bigint, @definition bigint, @digest binary(32);
EXEC model.put_semantic_definition 'TRANSFORMATION', N'sidefx:capability:obtain-governed-model-response', N'resolve-model-alias-embodiment.v1',
  N'{"id":"resolve-model-alias-embodiment.v1","expression":{"bindings":{"conveyor":{"else":{"op":"literal","value":{"authorityType":"model-provider-conveyor-authority.v1","conveyorId":"capability-authoring-model-conveyor.v1","maximumProviderSwitches":1,"providers":[{"adapterIdentity":"gemini-generate-content.v1","allowedResponseHeaders":["content-type","x-goog-request-id"],"credentialReference":"LOC_GEMINI_API_KEY","endpointAuthorityDigest":"sha256:57ab352b0978dca5e5ce33a28ccd7027c20df96da4138dbc7e8088f7c8fb0c04","models":[{"alias":"instruction-capable-model","resolvedModel":"gemini-2.5-pro"},{"alias":"reasoning-capable-model","resolvedModel":"gemini-2.5-flash"}],"providerAuthorityId":"primary-cognitive-provider","providerKind":"gemini"},{"adapterIdentity":"openai-chat-completions.v1","allowedResponseHeaders":["content-type","x-request-id"],"credentialReference":"LOC_OPENAI_API_KEY","endpointAuthorityDigest":"sha256:b70b8bc81f93ef949d7ae6cabbf71a56b4af2440c5489c5c4037923b534f0109","models":[{"alias":"instruction-capable-model","resolvedModel":"gpt-4.1-mini"}],"providerAuthorityId":"secondary-cognitive-provider","providerKind":"openai"}],"switchRules":[]}},"op":"if","then":{"from":"input","op":"path","path":"providerConveyor"},"when":{"left":{"from":"input","op":"path","path":"providerConveyor.authorityType"},"op":"equals","right":{"op":"literal","value":"model-provider-conveyor-authority.v1"}}},"requestProvider":{"from":"input","op":"path","path":"modelRequest.providerAuthorityId"},"providerEntry":{"as":"provider","from":{"from":"conveyor","op":"path","path":"providers"},"op":"find","where":{"left":{"from":"provider","op":"path","path":"providerAuthorityId"},"op":"equals","right":{"from":"requestProvider","op":"path","path":""}}},"requestAlias":{"from":"input","op":"path","path":"modelRequest.modelAlias"},"aliasEntry":{"else":{"op":"literal","value":null},"op":"if","then":{"as":"model","from":{"from":"providerEntry","op":"path","path":"models"},"op":"find","where":{"left":{"from":"model","op":"path","path":"alias"},"op":"equals","right":{"from":"requestAlias","op":"path","path":""}}},"when":{"from":"providerEntry","op":"path","path":""}},"substitutionRequested":{"else":{"op":"literal","value":false},"op":"if","then":{"from":"input","op":"path","path":"modelRequest.providerSubstitutionRequested"},"when":{"from":"input","op":"path","path":"modelRequest.providerSubstitutionRequested"}}},"op":"let","value":{"op":"merge","values":[{"from":"input","op":"path","path":""},{"fields":{"payload":{"else":{"fields":{"rejectedAlias":{"from":"requestAlias","op":"path","path":""},"rejectedProviderAuthority":{"from":"requestProvider","op":"path","path":""},"resolutionStatus":{"op":"literal","value":"ALIAS_REJECTED"}},"op":"object"},"op":"if","then":{"fields":{"adapterIdentity":{"from":"providerEntry","op":"path","path":"adapterIdentity"},"aliasResolutionLineage":{"fields":{"modelAlias":{"from":"requestAlias","op":"path","path":""},"providerAuthority":{"from":"requestProvider","op":"path","path":""}},"op":"object"},"credentialReference":{"from":"providerEntry","op":"path","path":"credentialReference"},"resolutionStatus":{"else":{"op":"literal","value":"EMBODIMENT_AUTHORIZED"},"op":"if","then":{"op":"literal","value":"SUBSTITUTION_NOT_AUTHORIZED"},"when":{"from":"substitutionRequested","op":"path","path":""}},"resolvedModel":{"from":"aliasEntry","op":"path","path":"resolvedModel"},"resolvedProviderAuthorityId":{"from":"providerEntry","op":"path","path":"providerAuthorityId"}},"op":"object"},"when":{"from":"aliasEntry","op":"path","path":""}}},"op":"object"}]}}}', @object OUTPUT, @definition OUTPUT, @digest OUTPUT;
GO
DECLARE @object bigint, @definition bigint, @digest binary(32);
