path":""},"when":{"left":{"from":"input","op":"path","path":"fixtureBypass"},"op":"equals","right":{"op":"literal","value":true}}},"when":{"left":{"from":"input","op":"path","path":"payload.resolutionStatus"},"op":"equals","right":{"op":"literal","value":"EMBODIMENT_AUTHORIZED"}}}}', @object OUTPUT, @definition OUTPUT, @digest OUTPUT;
GO

-- ============================== VERIFICATION ==============================
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
SELECT '1_binding_order' AS result_set, d.declared_id,
  CASE WHEN d.declared_id=N'resolve-model-alias-embodiment.v1'
       THEN CASE WHEN CONVERT(nvarchar(max),d.definition_json) LIKE N'%"bindings":{"conveyor"%' THEN 1 ELSE 0 END
       ELSE CASE WHEN CONVERT(nvarchar(max),d.definition_json) LIKE N'%"bindings":{"provider"%' THEN 1 ELSE 0 END
  END AS dependency_order_first
FROM analysis.v_selected_semantic_definition d
WHERE d.estate_model_pk=@estate AND d.object_kind='TRANSFORMATION'
  AND d.declared_id IN (N'resolve-model-alias-embodiment.v1', N'construct-projected-model-invocation.v1')
ORDER BY d.declared_id;
COMMIT TRANSACTION;
